from pathlib import Path
p=Path('work/ppolpet/shared/pet-render.js')
s=p.read_text()
s=s.replace("body: '#f3f0ec', inner: '#f2a6b6'", "body: '#fffaf7', inner: '#ffc0d2'").replace("blush: '#f2899f'", "blush: '#ffacc6'")
s=s.replace('const RX = 0.92, RY = 0.76, RZ = 0.8;', 'const RX = 0.96, RY = 0.76, RZ = 0.72;')
s=s.replace('EYE_LON = 0.35', 'EYE_LON = 0.43').replace('PX(0.165 * T.eyeSize)', 'PX(0.112 * T.eyeSize)').replace('PX(0.042)', 'PX(0.027)')
s=s.replace("roughness: 0.9, metalness: 0, clearcoat: 0", "roughness: 0.83, envMapIntensity: 0.45, metalness: 0, clearcoat: 0")
s=s.replace('sheen: 0.55', 'sheen: 0.15').replace('emissiveIntensity: 0.5', 'emissiveIntensity: 0.05')
s=s.replace('g.position.copy(p); g.rotation.set(-0.08', "g.position.set(p.x * 1.18, p.y + 0.04, -0.06); g.rotation.set(-0.08")
s=s.replace('[[0.06, 0.14], [0, 0], [-0.06, -0.14]]', '[[0.045, 0.12], [-0.045, -0.12]]')
s=s.replace("renderer.toneMappingExposure = 1.15", "renderer.toneMappingExposure = 1.08")
s=s.replace("'#d8cdd6', 0.6", "'#d5d5ec', 0.75").replace("'#fff6ee', 0.55", "'#fff9f5', 1.5")
s=s.replace('key.position.set(1.0, 6, 2.6)', 'key.position.set(-3.5, 6, 5)')
s=s.replace("new THREE.ShadowMaterial({ opacity: 0.06 })", "new THREE.ShadowMaterial({ opacity: 0.035 })")
s=s.replace("rgba(60,90,100,0.32)", "rgba(60,90,100,0.22)")
s=s.replace("full: { pos: [0, 1.65, 7.6], at: [0, 1.16, 0], fov: 21 }", "full: { pos: [0, 1.55, 8.2], at: [0, 1.16, 0], fov: 21 }")
s=s.replace("face: { pos: [0, 1.04, 3.9], at: [0, 0.93, 0], fov: 15 }", "face: { pos: [0, 1.4, 5.7], at: [0, 1.17, 0], fov: 23 }")
s=s.replace('dt * 0.0125', 'dt * 0.0105').replace('yaw = st.dir * 0.55', 'yaw = st.dir * 0.42')
s=s.replace('Math.abs(c) * 0.05', 'Math.abs(c) * 0.033').replace('roll = w * 0.13', 'roll = w * 0.075')
s=s.replace('w * 0.6', 'w * 0.32').replace('Math.sin(p * 2) * 0.6', 'Math.sin(p - 0.5) * 0.36')
s=s.replace('yaw = st.dir * 0.12', 'yaw = st.dir * 0.035').replace('Math.sin(t * 0.0013) * 0.07', 'Math.sin(t * 0.0013) * 0.035')
s=s.replace('const h = (t % 680) / 680, air = h < 0.62 ? Math.sin((h / 0.62) * Math.PI) : 0;', "const h = ((t - (st.enteredAt || 0)) % 920) / 920;\n      const air = h > 0.18 && h < 0.72 ? Math.sin((h - 0.18) / 0.54 * Math.PI) : 0;\n      const crouch = h <= 0.18 ? Math.sin(h / 0.18 * Math.PI) : h >= 0.72 ? Math.sin((h - 0.72) / 0.28 * Math.PI) : 0;")
s=s.replace('stretch = air > 0.05 ? air * 0.08 : -Math.sin(((h - 0.62) / 0.38) * Math.PI) * 0.12;', 'stretch = air * 0.055 - crouch * 0.09;')
s=s.replace('Math.sin(t * 0.018) * 0.35', 'Math.sin(t * 0.010) * 0.24')
s=s.replace("setState(s) { st.state = s; }", "setState(s) { if (st.state !== s) { st.enteredAt = performance.now(); st.phase = 0; } st.state = s; },\n      setAngle(a) { st.angle = a; },\n      setPaused(p) { st.paused = !!p; }")
s=s.replace('pose(built, st, t, dt);', "if (!st.paused) pose(built, st, t, dt);\n      if (st.angle != null) built.char.rotation.y = st.angle;")
# dispose temporary studio geometry, including light panels
s=s.replace('pm.dispose(); room.geometry.dispose(); room.material.dispose();', 'pm.dispose(); s.traverse(o => { if (o.isMesh) { o.geometry.dispose(); o.material.dispose(); } });')
s=s.replace('built.dispose(); renderer.dispose(); container.innerHTML', 'built.dispose(); scene.environment.dispose(); renderer.dispose(); container.innerHTML')
# calm curated random combinations
s=s.replace("'#5b5f9e'", "'#b6a5e6'").replace("'#c0566a'", "'#f4a2b9'").replace("'#4a4552'", "'#ddd9ef'")
s=s.replace('blush: Math.random() < 0.3', 'blush: true').replace('slice(0, 2)', 'slice(0, 1)')
p.write_text(s)
